"""
    Returns reverse complement of seq, with
    any non-ACTG characters replaced with Ns

    """
def reverse_complement(seq: Any) -> object {
    transform = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C', 'N': 'N'};
    try {
        comp = [transform[e] for e in seq];
    } except KeyError {
        seq = [e if (e in "ACTGN") else "N" for e in seq];
        comp = [transform[e] for e in seq];
    }
    rev_comp = comp[::-1];
    rev_comp_string = ''.join(rev_comp);
    return rev_comp_string;
}

"""N is length of arr
    """
def searchsorted(arr: Any, x: Any, N: Any = -1) -> object {
    if (N == -1) {
        N = len(arr);
    }
    L = 0;
    R = N - 1;
    done = False;
    eq = False;
    m = (L + R) // 2;
    while not done {
        xm = arr[m];
        if (xm < x) {
            L = m + 1;
        } elif (xm > x) {
            R = m - 1;
        } elif (xm == x) {
            L = m;
            eq = True;
            done = True;
        }
        m = (L + R) // 2;
        if (L > R) {
            done = True;
        }
    }
    return (L, eq);
}

"""Function checking if a number is odd.

    Args:
        x (float): Number to check.

    Returns:
        bool: True if the number is odd, False otherwise.
    """
def is_odd(x: float) -> object {
    return ((x % 2) == 1);
}

"""Determine the number of leading b's in vector x.

    Parameters
    ----------
    b: int
        Integer for counting at head of vector.
    x: array
        Vector of integers.

    Returns
    -------
    head: int
        Number of leading b's in x.
    """
def head(_b: Any, _x: Any) -> object {
    _head = 0;
    for i in _x {
        if (i == _b) {
            _head += 1;
        } else {
            break;
        }
    }
    return _head;
}

"""
    Return a list that contains of all the elements of lists without
    duplicates and maintaining the order.
    """
def _union_lists(lists: Any) -> object {
    seen = {};
    return [
        seen.setdefault(x, x) for l in lists
        for x in l
        if (x not in seen)
    ];
}

