"""
    maintain invariant of arr[low] < key <= arr[high]
    """
def binary_search_return_first_invariant(
    arr: Any, low: Any, high: Any, key: Any
) -> object {
    if (arr[low] >= key) {
        return low;
    }
    if (arr[high] < key) {
        return (high + 1);
    }
    while ((low + 1) < high) {
        mid = (low + high) // 2;
        if (arr[mid] < key) {
            low = mid;
        } else {
            high = mid;
        }
    }
    return high;
}

